from corpus_revision_authoring import add,Q,save

add('P22-G1-S1-01','교실의 자리는 하는 일이 달라요',
'''우리 교실 앞에는 칠판이 있어요. 칠판에는 모두 함께 볼 말을 써요. 뒤에는 책장이 있어요. 책장에는 읽을 책을 꽂아요. 물건을 두는 자리는 그 물건을 어떻게 쓸지 생각해서 정해요.
민지는 읽던 책을 칠판 아래에 놓았어요. 준호는 책을 찾다가 책장을 살폈어요. 민지는 책을 책장에 옮겼어요. 정한 자리에 놓으면 다음에 쓸 친구가 찾기 쉬워요.''',
'''선생님이 오늘 할 일을 알려 주었어요. 민지는 그 말을 공책 안에만 쓰면 다른 친구가 보기 어렵다고 생각했어요. 그래서 모두 볼 칠판에 적었어요. 함께 알릴 말과 보관할 책은 놓을 곳이 달라요.''',
'''새 교실에서는 책장이 앞에 있고 칠판이 옆에 있었어요. 준호는 책을 뒤로 가져가다가 멈추었어요. 뒤라는 곳만 외우면 책을 찾기 어려워요. 자리가 바뀌어도 책을 꽂는 물건은 책장이에요. 물건의 이름과 하는 일을 함께 살피면 새 교실에서도 알맞은 곳을 찾을 수 있어요.''',
[Q('읽을 책을 꽂는 물건은 무엇인가요?','책장이에요.',1,'책장에는 읽을 책을 꽂아요.'),Q('민지가 책을 책장에 옮긴 까닭은 무엇인가요?','다음 친구가 정한 자리에서 찾기 쉽기 때문이에요.',[1,2],'정한 자리에 놓으면'),Q('친구 모두에게 알릴 말을 쓰려면 어디를 쓰면 좋을까요?','모두 함께 볼 말을 쓰는 칠판이 좋아요.',1,'모두 함께 볼 말'),Q('‘책은 교실 뒤에만 놓아야 해.’라는 말에서 다시 살필 것은 무엇인가요?','뒤라는 곳보다 책을 꽂는 책장인지 살펴야 해요.',1,'책장에는 읽을 책을 꽂아요.')],
('새 교실의 책장은 창가에 있어요. 읽은 책을 정리하려고 해요.','어디에 놓는 것이 알맞나요?',['창가의 책장','책장이 없는 교실 뒤','모두 보는 칠판 앞'],[1,2],'물건의 쓰임과 정한 자리를 함께 생각해요.',['책을 보관하는 곳이에요.','이전 교실의 위치만 따랐어요.','알릴 말을 쓰는 곳과 책을 두는 곳을 섞었어요.']),[('자리','물건을 두거나 사람이 있는 곳')],'위치 재인에서 쓰임·공동 사용·위치 변경 적용으로 확장.')

add('P22-G1-S1-02','공과 상자를 살펴요',
'''지수는 공과 빈 상자를 책상 위에 놓았어요. 공은 둥글고, 상자에는 평평한 면이 있어요. 공을 살짝 밀자 굴러갔어요. 상자는 넓고 평평한 면을 아래로 놓으니 가만히 서 있었어요.
지수는 공 위에 다른 공을 올려 보았어요. 위의 공은 옆으로 굴러떨어졌어요. 상자 위에는 작은 상자를 놓을 수 있었어요. 같은 일을 하려 해도 물건의 모양에 따라 결과가 달라져요.''',
'''지수는 작은 자동차를 굴리는 놀이를 하려고 했어요. 공은 잘 굴러가지만 상자처럼 물건을 담을 수는 없어요. 상자는 물건을 담기 좋지만 공처럼 어느 쪽으로나 잘 굴러가지는 않아요. 하려는 일을 먼저 생각해야 해요.''',
'''친구가 상자는 무조건 잘 쌓인다고 말했어요. 지수는 큰 상자를 작은 상자 위에 올리면 기울 수 있다고 말했어요. 평평한 면이 있는지뿐 아니라 아래에서 잘 받쳐 주는지도 살펴야 해요. 한 번 잘 되었다고 어떤 상자든 아무렇게나 쌓아도 된다고 할 수는 없어요.''',
[Q('살짝 밀었을 때 굴러간 것은 무엇인가요?','공이에요.',1,'공을 살짝 밀자 굴러갔어요.'),Q('두 공을 쌓기 어려웠던 까닭은 무엇인가요?','공이 둥글어 위의 공이 옆으로 굴렀기 때문이에요.',[1,2],'옆으로 굴러떨어졌어요.'),Q('물건을 담아 가만히 놓으려면 공과 빈 상자 중 무엇을 고를까요?','물건을 담고 평평한 면으로 세울 수 있는 상자를 골라요.',1,'빈 상자'),Q('‘모양이 달라도 쌓이는 모습은 같아.’라는 말이 맞나요?','아니에요. 공은 굴러떨어지고 상자는 쌓였어요.',2,'위의 공은 옆으로 굴러떨어졌어요.')],
('둥근 공 둘과 같은 크기의 단단한 상자 둘이 있어요. 낮은 탑을 쌓으려 해요.','무엇을 고르면 좋을까요?',['평평한 면을 맞춘 상자 둘','둥근 면을 맞춘 공 둘','공 위에 올린 상자'],[1,2],'받치는 면이 평평한 상자를 고르는 것이 본문의 관찰과 맞아요.',['관찰한 모양과 결과를 적용했어요.','굴러가는 성질을 놓쳤어요.','아래 공이 굴러갈 수 있어요.']),[('평평하다','기울거나 둥글지 않고 반듯하다')],'공·상자의 관찰을 쌓기 목적과 연결하고 지나친 일반화를 점검.')

add('P22-G1-S2-01','아침의 차례를 살펴요',
'''민지는 아침에 일어나 세수를 해요. 다음에는 아침밥을 먹어요. 밥을 먹은 뒤에는 전날 챙긴 가방을 메요. 마지막으로 가족에게 인사하고 학교로 가요. 이 글은 민지가 오늘 한 일을 차례대로 적은 글이에요.
민지는 가방을 멘 채로 밥을 먹으려다가 가방을 내려놓았어요. 가방이 의자에 걸려 불편했기 때문이에요. 밥을 다 먹은 뒤 가방을 메니 움직이기 편했어요.''',
'''민지는 아침 일을 그림 카드로 만들었어요. ‘밥 먹기’와 ‘가방 메기’ 사이에 화살표를 그었어요. 화살표를 따라가면 무엇을 먼저 하고 무엇을 나중에 했는지 알 수 있어요. 두 일을 한꺼번에 했다는 뜻은 아니에요.''',
'''다음 날에는 가족에게 먼저 인사한 뒤 세수를 했어요. 민지는 오늘의 카드 차례를 고쳤어요. 어제의 글과 다르다고 오늘의 일이 틀린 것은 아니에요. 있었던 일을 적을 때에는 그날 실제로 한 차례와 맞아야 해요. 안내한 차례와 실제로 한 차례가 같은지도 살펴볼 수 있어요.''',
[Q('밥을 먹은 다음에 한 일은 무엇인가요?','가방을 멨어요.',1,'밥을 먹은 뒤에는'),Q('민지가 가방을 내려놓은 까닭은 무엇인가요?','가방이 의자에 걸려 밥 먹기가 불편했기 때문이에요.',2,'가방이 의자에 걸려 불편했기 때문이에요.'),Q('‘세수하기 → 가방 메기 → 밥 먹기’는 오늘의 글과 어디가 다른가요?','밥 먹기와 가방 메기의 차례가 바뀌었어요.',1,'다음에는 아침밥을 먹어요.'),Q('민지가 한 차례를 모든 친구가 꼭 따라야 한다고 할 수 있나요?','이 글은 민지가 오늘 한 일을 적었으므로 모두의 규칙이라고 할 수 없어요.',1,'민지가 오늘 한 일')],
('준호는 양치한 뒤 책을 읽고, 마지막에 잠자리에 들었어요.','준호가 한 일을 바르게 이은 것은 무엇인가요?',['양치하기 → 책 읽기 → 잠자리에 들기','책 읽기 → 양치하기 → 잠자리에 들기','잠자리에 들기 → 책 읽기 → 양치하기'],[1],'‘뒤’와 ‘마지막’이 알려 주는 차례를 새 글에도 적용해요.',['차례말과 맞아요.','앞의 두 일을 바꾸었어요.','앞뒤를 거꾸로 읽었어요.']),[('차례','앞에 한 일과 뒤에 한 일의 순서')],'순서 찾기에 실제 상황, 순서 재구성, 기록과 규칙의 차이를 보강.')

add('P22-G1-S2-02','이름표는 보이게 붙여요',
'''민수는 공책에 이름표를 붙여요. 먼저 종이 앞면에 이름을 써요. 다음에는 종이 뒷면에 풀을 발라요. 마지막으로 공책 앞면에 붙여요. 이름을 쓴 면이 밖으로 보여야 내 공책을 찾기 쉬워요.
민수는 친구의 이름표를 보았어요. 종이는 잘 붙었는데 이름이 보이지 않았어요. 이름을 쓴 면을 공책 쪽으로 붙였기 때문이에요. 친구는 새 이름표의 방향을 살펴서 붙였어요.''',
'''민수와 친구는 공책을 나란히 두었어요. 두 공책의 색은 같았지만 이름은 달랐어요. 이름표를 읽으니 누구의 공책인지 알 수 있었어요. 색만 보고 고르면 남의 공책을 가져갈 수도 있어요.''',
'''친구는 이름을 아주 작게 쓴 표를 보여 주었어요. 바깥으로 붙였지만 멀리서는 읽기 어려웠어요. 표가 잘 붙었는지, 이름이 보이는지, 글씨를 읽을 수 있는지를 함께 살펴야 해요. 이름표를 만드는 목적은 종이를 붙이는 데서 끝나지 않고 주인을 알리는 데 있어요.''',
[Q('풀은 종이의 어느 면에 바르나요?','이름을 쓰지 않은 뒷면이에요.',1,'종이 뒷면에 풀을 발라요.'),Q('친구의 이름이 보이지 않은 까닭은 무엇인가요?','이름을 쓴 면을 공책 쪽으로 붙였기 때문이에요.',2,'이름을 쓴 면을 공책 쪽으로'),Q('이름표가 바르게 붙었는지 살피려면 무엇을 보아야 하나요?','이름을 쓴 면이 밖으로 보이는지 살펴요.',1,'이름을 쓴 면이 밖으로'),Q('‘종이가 떨어지지 않으면 이름표는 잘 붙인 거야.’에서 빠진 것은 무엇인가요?','누구의 공책인지 알 수 있도록 이름이 보이는지도 보아야 해요.',[1,2],'내 공책을 찾기 쉬워요.')],
('같은 모양의 물통 두 개에 이름표를 붙이려고 해요.','이름표의 목적에 맞는 방법은 무엇인가요?',['이름을 읽을 수 있는 면을 밖으로 붙여요.','이름이 지워지지 않게 안쪽으로 숨겨요.','이름 없이 종이만 단단히 붙여요.'],[1,2],'물건이 바뀌어도 주인을 알리려면 이름을 읽을 수 있어야 해요.',['주인을 알릴 수 있어요.','이름을 숨기면 읽을 수 없어요.','단단히 붙인 것만으로 주인을 알 수 없어요.']),[('앞면','앞으로 보이게 한 쪽')],'과정의 목적과 실제 오류를 연결하는 활동으로 개정.')

add('G1-EXP-V1-1','꽃을 보고 개나리를 찾아요',
'''봄날, 민지는 길가에서 개나리를 보았어요. 꽃은 노란색이고 꽃잎이 네 갈래로 갈라져 있었어요. 긴 가지에 작은 꽃이 여러 개 피어 있었어요. 민지는 본 색과 모양을 수첩에 적었어요.
옆에는 노란 민들레도 있었어요. 두 꽃은 모두 노랗지만 생긴 모양이 달랐어요. 민지는 노랗다는 말 하나만으로 꽃 이름을 정하지 않았어요. 가지에 달린 모습과 꽃의 모양도 함께 살폈어요.''',
'''민지는 개나리가 가장 먼저 피는 꽃이라고 쓰려다가 멈추었어요. 오늘 본 두 꽃 말고 다른 꽃은 아직 살펴보지 않았기 때문이에요. 그래서 ‘오늘 길가에서 노란 개나리를 보았다.’라고 고쳤어요. 본 것과 아직 모르는 것을 나누어 적은 거예요.''',
'''친구는 멀리서 노란 꽃을 보고 개나리라고 말했어요. 가까이 가 보니 낮은 풀에서 핀 꽃이었어요. 멀리서 보이는 색은 단서 하나가 될 수 있지만 그것만으로 이름이 정해지지는 않아요. 민지는 꽃을 꺾지 않고 가까이에서 모양을 다시 보았어요. 확인할 단서가 더 있으면 처음 생각을 고칠 수 있어요.''',
[Q('민지가 본 개나리 꽃은 무슨 색인가요?','노란색이에요.',1,'꽃은 노란색'),Q('노란색만으로 개나리를 정하지 않은 까닭은 무엇인가요?','민들레도 노랗기 때문에 모양을 함께 보아야 해요.',[1,2],'두 꽃은 모두 노랗지만'),Q('노란 꽃이 낮은 풀에서 피었다면 무엇을 더 살펴야 할까요?','가지에 달렸는지와 꽃의 모양을 살펴야 해요.',2,'가지에 달린 모습과 꽃의 모양'),Q('‘노란 꽃은 모두 개나리야.’라는 말은 글과 맞나요?','노란 민들레도 있으므로 맞지 않아요.',2,'노란 민들레도 있었어요.')],
('노란 꽃 두 종류가 있어요. 하나는 긴 가지에 네 갈래 꽃이 피었고, 다른 하나는 풀에서 피었어요.','개나리를 찾을 때 더 알맞은 방법은 무엇인가요?',['색과 가지, 꽃 모양을 함께 봐요.','노란 것은 모두 개나리라고 해요.','가까운 꽃을 먼저 개나리라고 해요.'],[1,2],'여러 특징이 맞는지 살펴야 해요.',['두 문단의 단서를 함께 썼어요.','공통 색만으로 이름을 정했어요.','거리는 꽃 이름의 근거가 아니에요.']),[('갈래','여러 쪽으로 나뉜 부분')],'가장 먼저 핀다는 단정을 없애고 관찰 범위·다중 단서 분류를 도입.')

add('G1-EXP-V1-2','코끼리의 몸이 하는 일',
'''코끼리는 긴 코로 먹이를 집어요. 코에 물을 담아 입으로 옮겨 마시기도 해요. 코는 단지 길게 늘어진 부분이 아니라 여러 일을 하는 몸의 한 부분이에요.
넓은 귀를 움직이면 몸을 식히는 데 도움이 돼요. 굵은 다리는 무거운 몸을 받쳐요. 코, 귀, 다리는 생긴 모습도 하는 일도 달라요. 몸의 한 부분을 설명할 때에는 모습과 하는 일을 함께 말하면 알기 쉬워요.''',
'''민지는 코끼리 그림 옆에 ‘길다’라고만 적었어요. 친구는 어느 부분이 길다는 것인지 물었어요. 민지는 ‘긴 코로 먹이를 집는다.’라고 고쳤어요. 몸의 이름과 모습을 짝지으면 어떤 부분을 설명하는지 분명해져요.''',
'''친구는 코끼리가 귀로 먹이를 집는다고 썼어요. 민지는 귀에 관한 문장을 다시 읽었어요. 귀가 넓다는 말과 먹이를 집는다는 말을 아무렇게나 붙이면 글과 다른 설명이 돼요. 따로 찾은 낱말을 연결할 때에도 같은 몸 부분에 대한 말인지 확인해야 해요.''',
[Q('먹이를 집는 몸 부분은 무엇인가요?','긴 코예요.',1,'긴 코로 먹이를 집어요.'),Q('코끼리의 귀와 다리는 어떤 일을 하나요?','귀는 몸을 식히는 데 돕고 다리는 몸을 받쳐요.',2,'굵은 다리는 무거운 몸을 받쳐요.'),Q('몸을 받치는 부분을 그림에서 찾으려면 무엇을 보나요?','굵은 다리를 보아요.',2,'다리는 무거운 몸을 받쳐요.'),Q('‘코끼리의 넓은 귀가 먹이를 집는다.’는 설명을 어떻게 고칠까요?','먹이를 집는 부분은 귀가 아니라 코라고 고쳐요.',[1,2],'코, 귀, 다리는 생긴 모습도 하는 일도 달라요.')],
('새 동물 카드에는 ‘긴 꼬리로 나뭇가지를 붙잡는다.’라고 적혀 있어요.','카드의 모습과 하는 일을 바르게 짝지은 것은 무엇인가요?',['긴 꼬리 — 나뭇가지 붙잡기','긴 귀 — 나뭇가지 붙잡기','긴 꼬리 — 먹이의 색 바꾸기'],[1,2],'새 카드에서도 몸 부분과 하는 일을 함께 읽어요.',['같은 부분의 정보를 이었어요.','몸 부분을 바꾸었어요.','카드에 없는 일을 보탰어요.']),[('받치다','아래에서 버티어 떨어지지 않게 하다')],'코로 직접 물을 마신다는 오해를 고치고 부분·기능의 정확한 연결을 연습.')

add('G1-EXP-V1-3','씻는 차례를 빠뜨리지 않아요',
'''놀이가 끝난 뒤 민지는 손을 씻었어요. 먼저 흐르는 물에 손을 적시고 비누 거품을 냈어요. 다음에는 손바닥과 손등, 손가락 사이를 골고루 문질렀어요. 그 뒤에는 물로 거품을 씻어 내고 깨끗한 수건으로 말렸어요.
민지는 손바닥만 문지르고 끝내려다가 손등과 손가락 사이도 살폈어요. 한 곳을 닦았다고 다른 곳까지 닦은 것은 아니에요. 빠뜨린 곳이 없는지 확인하는 것도 차례를 따라 하는 일에 들어가요.''',
'''민지는 글을 읽으며 그림 카드 네 장을 놓았어요. 적시고 거품 내기, 골고루 문지르기, 거품 씻기, 말리기를 차례로 이었어요. ‘그 뒤’라는 말이 앞의 일이 끝난 다음에 할 일을 알려 주었어요.''',
'''친구는 거품을 씻기 전에 수건으로 닦으려고 했어요. 민지는 카드의 앞뒤를 다시 보자고 했어요. 모든 카드가 있다고 바른 차례가 되는 것은 아니에요. 빠진 일이 없는지와 앞뒤가 맞는지를 따로 살펴야 해요. 잘못 놓은 카드 한 장을 옮기면 왜 옮겼는지도 말해 보아요.''',
[Q('거품을 낸 다음에 한 일은 무엇인가요?','손의 여러 곳을 골고루 문질렀어요.',1,'다음에는 손바닥과 손등'),Q('손가락 사이도 살핀 까닭은 무엇인가요?','손바닥만 닦으면 빠진 곳이 있을 수 있기 때문이에요.',[1,2],'한 곳을 닦았다고 다른 곳까지'),Q('거품이 남아 있는데 수건으로 말리려 하면 어떤 일을 먼저 해야 하나요?','물로 거품을 씻어 내야 해요.',1,'물로 거품을 씻어 내고'),Q('‘손바닥을 닦았으니 모두 끝났어.’라는 말에서 빠진 것은 무엇인가요?','손등과 손가락 사이도 닦았는지 확인해야 해요.',2,'손등과 손가락 사이도 살폈어요.')],
('붓을 씻는 안내에 ‘물에 헹군 뒤 물기를 닦고, 마지막으로 통에 넣는다.’라고 쓰여 있어요.','물기를 닦기 전에 해야 할 일은 무엇인가요?',['물에 헹구기','통에 넣기','통을 닫고 끝내기'],[1],'새 안내에서도 앞뒤를 알려 주는 말을 따라가요.',['‘뒤’의 앞에 있는 일이에요.','마지막 일을 앞으로 옮겼어요.','안내에 없는 일을 넣었어요.']),[('골고루','어느 곳도 빠뜨리지 않고 고르게')],'건강 효능 단정 없이 실제 과정의 누락·순서 판단을 다루도록 수정.')

add('G1-EXP-V1-4','도움이 필요한 곳에 맞는 차',
'''소방서에는 서로 다른 일을 하는 차가 있어요. 펌프차는 물을 보내 불을 끄는 일을 도와요. 사다리차는 높은 곳에 닿을 수 있는 사다리를 써요. 구급차는 다치거나 아픈 사람을 병원으로 옮기는 일을 해요.
세 차는 모두 사람을 돕지만 같은 도구를 쓰는 것은 아니에요. 차 이름만 외우기보다 어떤 도움이 필요한지와 차가 하는 일을 이어 보아요. 한 사건에 서로 다른 차가 함께 갈 수도 있어요.''',
'''민지는 높은 창문 그림 옆에 사다리차 카드를 놓았어요. 병원으로 옮겨야 하는 사람 그림 옆에는 구급차 카드를 놓았어요. 두 카드 모두 ‘사람을 돕는다’는 말만으로는 서로 구별하기 어려웠어요.''',
'''친구는 한 사건에는 차 한 대만 간다고 생각했어요. 하지만 높은 곳에서 구조한 사람을 병원으로 옮겨야 할 수도 있어요. 필요한 도움이 여럿이면 하는 일이 다른 차가 함께 도와요. 실제 출동은 구조하는 사람이 상황을 판단해 정해요. 우리는 글에서 각 차의 역할을 구별해 보아요.''',
[Q('병원으로 사람을 옮기는 차는 무엇인가요?','구급차예요.',1,'구급차는 다치거나 아픈 사람을 병원으로'),Q('세 차의 같은 점과 다른 점을 하나씩 말해 보세요.','모두 사람을 돕지만 쓰는 도구와 하는 일이 달라요.',[1,2],'모두 사람을 돕지만'),Q('높은 곳에 닿는 도구를 찾을 때 어떤 차의 설명을 읽어야 하나요?','사다리차의 설명을 읽어요.',1,'높은 곳에 닿을 수 있는 사다리'),Q('‘모두 사람을 도우니 아무 차나 같은 일을 해.’가 맞나요?','도구와 하는 일이 달라서 같은 일을 한다고 할 수 없어요.',2,'같은 도구를 쓰는 것은 아니에요.')],
('그림 속에는 높은 곳에 닿는 도움과 병원으로 옮기는 도움이 모두 필요해요.','글에 맞는 생각은 무엇인가요?',['서로 다른 차가 함께 도울 수 있어요.','모든 차는 병원으로 옮기는 일만 해요.','한 사건에는 차 한 대만 도울 수 있어요.'],[1,2],'필요한 역할이 다르면 함께 도울 수 있어요.',['여러 역할을 연결했어요.','하나의 역할로 모두를 설명했어요.','글에 없는 제한을 만들었어요.']),[('역할','맡아서 하는 일')],'단순 역할 대응에서 공통·차이 및 복합 필요 상황으로 확대.')

add('G1-EXP-V2-1','몸 색을 보고 무엇을 알까요?',
'''카멜레온은 몸 색이 달라질 수 있는 동물이에요. 다른 카멜레온에게 신호를 보내거나 몸이 처한 상태에 따라 색이 달라져요. 햇빛과 온도도 색에 영향을 줄 수 있어요.
초록 잎 위에 있다고 언제나 잎과 똑같은 초록색이 되는 것은 아니에요. 몸 색 하나만 보고 왜 색이 달라졌는지 딱 정하기는 어려워요. 같은 자리에서 앞뒤 모습을 살피고 주변 상태도 함께 보아야 해요.''',
'''민지는 사진 한 장을 보고 카멜레온이 화가 났다고 말했어요. 준호는 사진에는 바뀌기 전의 색과 온도가 없다고 했어요. 사진에 보이는 색은 말할 수 있어도, 색이 달라진 까닭은 더 살펴야 해요.''',
'''두 사진에서 카멜레온의 색이 달랐어요. 그런데 찍은 시각도 다르고 햇빛도 달랐어요. 민지는 잎의 색만 달라서 몸 색이 바뀌었다고 말하지 않았어요. 함께 달라진 것이 있다면 까닭을 하나로 정하기 어려워요. 궁금한 점을 남겨 두는 것도 자세히 보는 방법이에요.''',
[Q('카멜레온의 몸 색에 영향을 줄 수 있는 것을 하나 말해 보세요.','햇빛이나 온도, 몸의 상태 등이에요.',1,'햇빛과 온도도'),Q('몸 색만 보고 까닭을 딱 정하기 어려운 이유는 무엇인가요?','색에 영향을 주는 것이 여럿이기 때문이에요.',[1,2],'몸 색 하나만 보고'),Q('몸 색이 바뀐 까닭을 살피려면 색 말고 무엇을 더 보면 좋을까요?','앞뒤 모습과 햇빛이나 온도 같은 주변 상태를 살펴요.',2,'주변 상태도 함께'),Q('‘초록 잎 위에서는 꼭 초록색이야.’라는 말은 글과 맞나요?','언제나 잎과 똑같아지는 것은 아니므로 맞지 않아요.',2,'언제나 잎과 똑같은')],
('카멜레온의 몸 색이 달라진 사진이 있어요. 찍은 때의 온도는 나와 있지 않아요.','알맞은 말은 무엇인가요?',['색은 달라졌지만 까닭은 더 살펴야 해요.','잎을 따라 바뀐 것이 틀림없어요.','몸 색이 달라지면 반드시 화가 난 거예요.'],[1,2],'보인 사실과 아직 모르는 까닭을 구별해요.',['확인한 범위를 지켰어요.','여러 까닭 중 하나를 단정했어요.','상태 한 가지만 원인이라고 정했어요.']),[('영향','어떤 것 때문에 다른 것이 달라지는 일')],'주변 색을 그대로 복사한다는 오류를 수정. 관찰과 원인 추론을 구별.', ['https://animals.sandiegozoo.org/animals/chameleon'])

add('G1-EXP-V2-2','신호와 차를 함께 살펴요',
'''민지는 어른과 함께 횡단보도 앞에 섰어요. 초록 불이 켜져도 바로 뛰지 않았어요. 왼쪽과 오른쪽을 살피고 차가 멈추었는지 확인했어요. 길을 건널 수 있는 신호와 차의 움직임을 함께 본 거예요.
어른이 물었어요. ‘초록 불인데 왜 기다렸니?’ 민지는 차 한 대가 아직 움직이고 있었다고 말했어요. 신호만 보고 차는 보지 않으면 놓치는 것이 있어요. 길을 건널 때에는 주변을 살피며 걸어요.''',
'''민지는 두 그림을 비교했어요. 두 그림 모두 초록 불이었지만, 한 그림에서는 차가 움직였고 다른 그림에서는 차가 멈추었어요. 같은 신호가 보인다고 주변 모습까지 모두 같은 것은 아니었어요.''',
'''친구가 손을 들기만 하면 언제나 안전하다고 말했어요. 민지는 먼저 멈추고 살피는 일도 필요하다고 했어요. 한 가지 행동을 했다는 이유로 다른 확인을 빼면 안 돼요. 그림 문제에서도 눈에 크게 보이는 신호 하나만 고르지 말고, 질문에 필요한 조건을 모두 찾아보아요.''',
[Q('민지가 초록 불과 함께 확인한 것은 무엇인가요?','차가 멈추었는지예요.',1,'차가 멈추었는지 확인했어요.'),Q('초록 불인데도 기다린 까닭은 무엇인가요?','차 한 대가 아직 움직였기 때문이에요.',2,'차 한 대가 아직 움직이고'),Q('그림에 신호만 있고 차의 움직임은 없다면 무엇을 더 확인해야 하나요?','차가 멈추었는지 확인해야 해요.',[1,2],'신호와 차의 움직임을 함께'),Q('‘초록 불만 확인하면 돼.’라는 말에서 빠진 것은 무엇인가요?','차와 주변을 살피는 일이 빠졌어요.',2,'신호만 보고 차는 보지 않으면')],
('놀이실 문에 ‘사용 가능’ 표시가 있어요. 안내에는 표시를 보고 안에 친구가 있는지도 살피라고 되어 있어요.','안내를 지킨 행동은 무엇인가요?',['표시와 방 안을 모두 살펴요.','표시만 보고 바로 들어가요.','친구가 있는지만 보고 표시는 보지 않아요.'],[1,2],'두 조건을 함께 확인하는 방법을 새 안내에도 써요.',['두 조건을 모두 확인했어요.','두 번째 조건을 빠뜨렸어요.','첫 번째 조건을 빠뜨렸어요.']),[('확인','맞는지 다시 살펴보는 일')],'위험을 한 동작으로 해결한다는 오해를 줄이고 복수 조건 확인으로 설계.')

add('G1-EXP-V2-3','놓는 방향을 바꾸면',
'''상자 모양은 평평한 면을 맞대면 쌓기 좋아요. 공 모양은 둥글어서 굴러가기 쉬워요. 둥근기둥 모양에는 평평한 면과 둥근 옆면이 함께 있어요.
민지는 둥근기둥 블록을 평평한 면으로 세웠어요. 위에 다른 블록을 올릴 수 있었어요. 이번에는 옆으로 눕히고 살짝 밀었어요. 블록이 굴러갔어요. 같은 블록도 어느 면을 바닥에 대는지에 따라 모습이 달라졌어요.''',
'''친구는 굴러가는 물건과 쌓이는 물건을 따로 나누었어요. 둥근기둥을 어느 쪽에 놓을지 망설였어요. 민지는 눕혔을 때와 세웠을 때를 나누어 적자고 했어요. 물건 이름 하나만으로 행동이 정해지지는 않아요.''',
'''새 블록은 한쪽이 둥글고 다른 쪽이 평평했어요. 친구들은 아직 해 보지 않았으니 어느 면으로 놓을 때 잘 굴러갈지 먼저 생각했어요. 그런 뒤 안전한 낮은 자리에서 살짝 밀어 보았어요. 생각한 것과 실제 모습을 비교하면 빠뜨린 조건을 찾을 수 있어요.''',
[Q('평평한 면과 둥근 옆면이 함께 있는 모양은 무엇인가요?','둥근기둥 모양이에요.',1,'평평한 면과 둥근 옆면'),Q('같은 블록인데 결과가 달라진 까닭은 무엇인가요?','바닥에 닿는 면을 바꾸었기 때문이에요.',2,'어느 면을 바닥에 대는지'),Q('둥근기둥을 굴리려면 어느 쪽으로 놓아야 할까요?','둥근 옆면이 바닥에 닿게 눕혀요.',2,'옆으로 눕히고 살짝 밀었어요.'),Q('‘한번 굴러간 블록은 세울 수 없어.’가 맞나요?','같은 블록을 평평한 면으로 세울 수 있으므로 맞지 않아요.',2,'평평한 면으로 세웠어요.')],
('둥근기둥 모양의 통을 가만히 세우려고 해요.','알맞은 방법은 무엇인가요?',['평평한 면을 바닥에 대요.','둥근 옆면을 바닥에 대고 밀어요.','굴러간 적이 있으니 세우지 못한다고 해요.'],[1,2],'물건의 이름뿐 아니라 놓는 면을 고려해요.',['목적과 닿는 면이 맞아요.','굴리는 조건을 적용했어요.','한 경우를 모든 경우로 넓혔어요.']),[('옆면','물건의 옆쪽에 있는 면')],'모양 분류를 방향 조건과 결과 변화로 확장.')

add('G1-EXP-V2-4','겨울을 나는 동물을 읽어요',
'''겨울에는 날씨가 추워지고 먹이를 찾기 어려워지기도 해요. 어떤 동물은 움직임을 줄이며 겨울을 보내요. 곰은 몸에 모아 둔 것을 쓰며 굴 같은 곳에서 겨울을 보내기도 해요.
개구리가 겨울을 나는 곳은 종류에 따라 달라요. 땅속이나 물속에서 겨울을 보내는 종류가 있어요. 동물마다 지내는 방법이 같지는 않아요. 한 동물의 모습만 보고 모든 동물이 같다고 말하면 안 돼요.''',
'''민지는 동물 카드에서 겨울을 나는 장소에 표시했어요. 곰 카드와 개구리 카드에는 서로 다른 장소가 적혀 있었어요. 두 동물이 겨울을 보낸다는 점은 같아도, 어디에서 어떻게 지내는지는 나누어 읽어야 해요.''',
'''친구는 개구리 한 종류가 물속에서 겨울을 보낸다는 글을 읽었어요. 그래서 모든 개구리가 물속에서 지낸다고 썼어요. 민지는 ‘한 종류’라는 말을 빠뜨렸다고 했어요. 글에 나온 대상이 누구인지 살피면 알고 있는 범위를 너무 넓히지 않을 수 있어요.''',
[Q('겨울에 동물이 먹이를 찾기 어려워질 수 있나요?','네. 겨울에는 먹이를 찾기 어려워지기도 해요.',1,'먹이를 찾기 어려워지기도'),Q('곰과 개구리를 읽을 때 같은 점과 다른 점은 무엇인가요?','겨울을 보낸다는 점은 같지만 장소와 방법이 달라요.',[1,2],'종류에 따라 달라요.'),Q('한 개구리의 겨울 장소를 알려면 무엇을 더 알아야 하나요?','어떤 종류의 개구리인지 알아야 해요.',2,'종류에 따라'),Q('‘개구리는 모두 따뜻한 땅속에서 잔다.’는 말은 글과 맞나요?','물속에서 지내는 종류도 있으므로 모두라고 하면 안 돼요.',2,'땅속이나 물속')],
('동물 카드에 ‘이 새는 겨울에 다른 곳으로 옮겨 간다.’라고 적혀 있어요.','카드로 알 수 있는 것은 무엇인가요?',['카드에 나온 새의 겨울 모습','모든 새가 겨울에 옮겨 간다는 사실','모든 동물이 겨울잠을 잔다는 사실'],[2],'대상의 범위를 지켜서 읽어요.',['카드가 말한 대상에 한정했어요.','한 새의 설명을 모든 새로 넓혔어요.','카드에 없는 내용을 모든 동물에게 적용했어요.']),[('종류','비슷한 것끼리 나눈 갈래')],'곰·개구리의 겨울 행동을 똑같은 방식으로 단정한 부분과 모든 개구리 땅속 표현 수정.', ['https://www.nps.gov/articles/the-science-of-hibernation.htm','https://home.nps.gov/yell/learn/nature/bear.htm'])

add('G1-EXP-V3-1','무엇으로 알아차렸을까요?',
'''우리는 여러 몸 부분으로 주변을 알아차려요. 눈으로 색과 모양을 보고, 귀로 소리를 들어요. 코로 냄새를 맡고 혀로 맛을 느껴요. 피부로 차갑거나 따뜻한 느낌을 알아차리기도 해요.
민지는 종소리를 듣고 고개를 돌렸어요. 그 뒤 눈으로 시계를 보았어요. 소리를 들은 일과 시계를 본 일에는 서로 다른 몸 부분을 썼어요. 하나의 일을 하면서 여러 감각을 함께 쓸 수도 있어요.''',
'''민지는 사과가 빨갛다고 말했어요. 빨간색은 눈으로 보았고, 아삭한 소리는 귀로 들었어요. 같은 사과를 설명해도 무엇을 알아차렸는지에 따라 연결되는 몸 부분이 달라요. 맛을 보지 않았다면 맛은 아직 모를 수 있어요.''',
'''친구가 모르는 병을 보고 냄새나 맛으로 알아보자고 했어요. 민지는 모르는 것은 맛보거나 함부로 만지지 말고 어른에게 묻자고 했어요. 감각을 배웠다고 무엇이든 직접 시험해야 하는 것은 아니에요. 안전하게 확인할 수 있는 정보와 더 물어야 할 정보를 구별해요.''',
[Q('종소리를 들을 때 쓰는 몸 부분은 무엇인가요?','귀예요.',[1,2],'귀로 소리를 들어요.'),Q('민지가 종소리와 시계를 알아차릴 때 어떤 두 부분을 썼나요?','귀로 소리를 듣고 눈으로 시계를 보았어요.',[1,2],'눈으로 시계를 보았어요.'),Q('사과의 색만 보았다면 맛까지 알았다고 할 수 있나요?','색과 맛은 다른 정보이므로 맛까지 알았다고 할 수 없어요.',1,'눈으로 색과 모양을 보고'),Q('‘하나의 일을 할 때는 감각 하나만 써.’라는 말이 맞나요?','여러 감각을 함께 쓸 수도 있으므로 맞지 않아요.',2,'여러 감각을 함께')],
('준호는 눈을 감고 북소리를 들었어요. 북의 색은 보지 못했어요.','알 수 있는 정보는 무엇인가요?',['북소리가 들렸다는 것','북이 빨간색이라는 것','북의 둥근 모양을 보았다는 것'],[1,2],'실제로 사용한 감각과 얻은 정보를 연결해요.',['들은 정보예요.','보지 않은 색을 보탰어요.','듣기와 보기를 섞었어요.']),[('감각','보고 듣는 것처럼 몸으로 알아차리는 느낌')],'다섯 감각이 전부라는 단정을 줄이고 얻은 정보의 범위를 판단.')

add('G1-EXP-V3-2','매미의 소리와 모습',
'''여름날 나무에서 큰 매미 소리가 들렸어요. 수컷 매미는 몸의 얇은 막을 움직여 큰 소리를 내요. 이 소리는 짝을 찾는 데 쓰여요. 소리를 들었다는 것과 매미를 직접 보았다는 것은 다른 일이에요.
민지는 나무 쪽에서 소리를 들었지만 매미는 찾지 못했어요. 그래서 수첩에 ‘나무 쪽에서 매미 소리가 들렸다.’라고 썼어요. 보지 않은 날개 색이나 매미 수는 적지 않았어요.''',
'''나중에 민지는 나뭇가지에 붙은 매미 한 마리를 보았어요. 이번에는 본 모습을 덧붙여 적었어요. 먼저 쓴 기록이 틀린 것은 아니에요. 새로 확인한 정보가 생긴 거예요. 들은 것과 본 것을 나누면 기록이 분명해져요.''',
'''친구는 소리가 크니 매미가 열 마리라고 말했어요. 하지만 소리의 크기만으로 정확한 수를 세기는 어려워요. 여러 소리가 겹칠 수도 있고 가까이 있는 소리가 크게 들릴 수도 있어요. 민지는 셀 수 있을 때 수를 적고, 아직 모르면 모른다고 남기기로 했어요.''',
[Q('수컷 매미가 큰 소리를 내는 것은 무엇을 찾는 데 쓰이나요?','짝을 찾는 데 쓰여요.',1,'짝을 찾는 데 쓰여요.'),Q('민지는 왜 날개 색을 적지 않았나요?','매미를 직접 보지 못했기 때문이에요.',2,'매미는 찾지 못했어요.'),Q('나중에 매미를 직접 보면 기록에 무엇을 더할 수 있나요?','직접 본 모습만 더할 수 있어요.',[1,2],'보지 않은 날개 색이나'),Q('‘소리를 들었으니 날개 색도 알았어.’라는 말은 맞나요?','들은 정보로 보지 않은 색을 알 수는 없어요.',[1,2],'직접 보았다는 것은 다른 일')],
('복도에서 발소리를 들었지만 문밖 사람은 보지 못했어요.','기록으로 알맞은 것은 무엇인가요?',['복도에서 발소리가 들렸다.','빨간 옷을 입은 친구가 왔다.','친구 세 명이 달려왔다.'],[2],'확인한 감각 정보만 기록해요.',['실제로 들은 정보예요.','보지 않은 색을 보탰어요.','확인하지 않은 수와 행동을 보탰어요.']),[('기록','보고 들은 것을 남긴 것')],'암컷은 어떤 소리도 못 낸다는 단정을 삭제하고 발음막 설명 및 관찰 범위로 개정.', ['https://www.si.edu/sidedoor/cicadapalooza'])

add('G1-EXP-V3-3','두 글에서 같은 말을 찾아요',
'''가 글에는 토끼의 귀가 길다고 나와요. 긴 귀를 세우고 주변 소리에 귀를 기울이는 모습도 설명해요. 나 글에도 토끼의 귀가 길다고 나와요. 나 글은 긴 뒷다리로 뛰는 모습과 짧은 꼬리도 설명해요.
두 글을 함께 읽으면 같은 특징과 한 글에만 나온 특징을 나눌 수 있어요. 두 글에 모두 나온 것은 긴 귀예요. 뒷다리와 꼬리는 나 글에 나와요. 가 글에 없다고 해서 토끼에게 뒷다리가 없다는 뜻은 아니에요.''',
'''민지는 종이를 세 칸으로 나누었어요. 가운데에는 두 글의 같은 말을, 양옆에는 각 글에서만 찾은 말을 적었어요. 같은 대상에 관한 글이어도 설명하는 부분이 모두 같지는 않아요.''',
'''다른 토끼 글에는 부드러운 털이 나왔어요. 민지는 새 글에서 읽은 말을 가 글의 내용이라고 옮겨 적지 않았어요. 어떤 글에서 얻은 정보인지도 함께 표시했어요. 여러 글을 연결할 때에는 정보를 더 많이 모으는 것과 나온 곳을 바르게 기억하는 것이 모두 필요해요.''',
[Q('두 글에 모두 나온 토끼의 특징은 무엇인가요?','귀가 길다는 점이에요.',[1,2],'두 글에 모두 나온 것은 긴 귀'),Q('긴 뒷다리는 어느 글에서 알 수 있나요?','나 글에서 알 수 있어요.',1,'나 글은 긴 뒷다리로'),Q('두 글을 함께 읽으면 가 글만 읽을 때보다 무엇을 더 알 수 있나요?','뒷다리와 꼬리의 특징을 더 알 수 있어요.',[1,2],'뒷다리와 꼬리는 나 글'),Q('가 글에 꼬리 이야기가 없으니 토끼는 꼬리가 없다고 해도 되나요?','쓰여 있지 않다는 것과 실제로 없다는 것은 달라요.',2,'없다는 뜻은 아니에요.')],
('가 글에는 우산의 둥근 덮개가, 나 글에는 둥근 덮개와 긴 손잡이가 나와요.','두 글에 모두 나온 것은 무엇인가요?',['둥근 덮개','긴 손잡이','빨간 우산'],[1,2],'각 글에 실제로 나온 정보를 비교해요.',['양쪽에 있는 정보예요.','나 글에만 있어요.','어느 글에도 없는 색이에요.']),[('특징','다른 것과 구별되는 모습')],'같은 정보 찾기에서 정보 출처와 미언급/부재의 구별까지 확장.')

add('G1-EXP-W1','필통 소개에 필요한 말',
'''민지는 새 친구에게 필통 속 물건을 소개하려고 해요. 연필은 글씨를 쓰는 데 쓰고, 지우개는 연필로 쓴 글씨를 지우는 데 써요. 두 물건은 함께 쓰지만 하는 일은 달라요.
민지는 ‘이것은 좋아요.’라고 썼어요. 친구는 무엇이 좋은지 알기 어렵다고 했어요. 민지는 ‘지우개는 틀린 연필 글씨를 지워요.’라고 고쳤어요. 물건 이름과 하는 일을 넣으니 설명이 분명해졌어요.''',
'''민지는 지우개의 색도 적었어요. 색을 알려 주면 필통에서 찾는 데 도움이 돼요. 쓰는 방법을 알려 주려면 하는 일이 더 중요할 수 있어요. 누구에게 무엇을 알려 주려는지에 따라 넣을 말을 골라요.''',
'''친구는 연필과 지우개를 소개하는 글에 어제 먹은 간식 이야기를 길게 붙였어요. 그 일은 재미있지만 필통 속 물건을 알려 주는 데에는 필요하지 않았어요. 쓴 말을 모두 남기기보다 글의 목적과 맞는 말을 고르는 것도 글쓰기예요.''',
[Q('연필로 쓴 글씨를 지우는 물건은 무엇인가요?','지우개예요.',1,'지우개는 연필로 쓴 글씨'),Q('고친 문장이 처음 문장보다 분명한 까닭은 무엇인가요?','물건 이름과 하는 일이 들어갔기 때문이에요.',2,'물건 이름과 하는 일'),Q('연필을 소개할 때 ‘이것은 좋아요.’를 어떻게 고칠 수 있나요?','연필은 글씨를 쓰는 물건이라고 쓸 수 있어요.',1,'연필은 글씨를 쓰는 데'),Q('‘지우개는 글씨를 쓰는 물건’이라는 문장은 맞나요?','연필과 지우개의 하는 일을 바꾸었으므로 고쳐야 해요.',1,'두 물건은 함께 쓰지만 하는 일은 달라요.')],
('가위를 모르는 친구에게 가위를 소개하려고 해요.','필요한 설명은 무엇인가요?',['가위는 종이를 자를 때 쓰는 도구예요.','이것은 정말 좋아요.','나는 어제 간식을 먹었어요.'],[1,2],'이름과 쓰임을 함께 알려 주어요.',['대상과 하는 일이 분명해요.','대상과 쓰임이 빠졌어요.','소개할 물건과 관계없어요.']),[('소개','모르는 사람에게 알도록 설명함')],'쓰기 지식을 본문 안의 실제 고쳐쓰기 사례와 목적 판단으로 전환.')

add('G1-EXP-W2','본 낙엽과 짐작한 말',
'''민지는 떨어진 나뭇잎 두 장을 보았어요. 한 장은 노랗고 부채처럼 넓었어요. 다른 한 장은 붉고 손바닥처럼 갈라져 있었어요. 민지는 색과 모양을 따로 적었어요.
친구는 ‘이 잎은 신이 났다.’라고 말했어요. 재미있는 생각이지만 눈으로 본 색이나 모양은 아니에요. 민지는 관찰한 것을 알리는 글에는 직접 확인한 말을 먼저 넣었어요. 자기 느낌은 느낌이라고 나누어 적었어요.''',
'''민지는 ‘예쁜 잎’이라는 말만 적은 그림을 친구에게 보여 주었어요. 친구는 두 잎 중 어느 잎인지 고를 수 없었어요. ‘노랗고 부채처럼 넓은 잎’이라고 고치자 가리키는 잎이 분명해졌어요.''',
'''며칠 뒤 같은 나무 아래에서 초록색이 조금 남은 잎도 보았어요. 민지는 한 장이 노랗다고 그 나무의 모든 잎이 똑같다고 쓰지 않았어요. 어느 잎을 언제 보았는지 남기면 기록을 다시 비교하기 좋아요. 색만 달라져도 모양은 비슷할 수 있어요.''',
[Q('첫 번째 잎의 색과 모양은 무엇인가요?','노랗고 부채처럼 넓어요.',1,'노랗고 부채처럼 넓었어요.'),Q('‘신이 났다’와 ‘노랗다’는 어떻게 다른가요?','노랗다는 본 색이고 신이 났다는 친구의 생각이에요.',[1,2],'눈으로 본 색이나 모양은 아니에요.'),Q('두 잎을 구별하려면 ‘예쁘다’ 말고 무엇을 쓰면 좋을까요?','본 색과 모양을 구체적으로 쓰면 좋아요.',1,'색과 모양을 따로'),Q('관찰 글에 ‘모든 잎이 빨갛다’고 써도 되나요?','본문에는 노란 잎도 있으므로 맞지 않아요.',1,'한 장은 노랗고')],
('돌 두 개를 보았어요. 하나는 회색이고 둥글며, 다른 하나는 검고 길쭉해요.','본 모습을 알리는 말은 무엇인가요?',['회색이고 둥근 돌','기분이 좋은 돌','모든 돌은 검다'],[1,2],'관찰한 색과 모양을 느낌이나 지나친 말과 구별해요.',['직접 본 두 특징이에요.','돌의 기분은 본 특징이 아니에요.','두 돌 중 하나의 색을 모두에게 적용했어요.']),[('관찰','모습이나 변화를 자세히 살펴봄')],'색의 일반화와 사실/느낌 혼동을 다루는 실제 관찰 사례로 수정.')

add('G1-EXP-W3','시계 설명의 앞뒤',
'''민지는 바늘이 있는 시계를 소개해요. 이 시계는 시간을 알려 주어요. 시계 앞면에는 숫자와 바늘이 있어요. 짧은바늘은 몇 시인지, 긴바늘은 몇 분인지 알려 주어요.
민지는 먼저 시계 전체가 하는 일을 썼어요. 그다음 짧은바늘과 긴바늘을 차례로 설명했어요. 어느 물건의 부분인지 먼저 알면 뒤의 설명을 따라 읽기 쉬워요. 두 바늘의 하는 일을 서로 바꾸어 쓰지 않도록 확인했어요.''',
'''친구는 ‘긴바늘은 몇 분인지 알려 준다.’라는 문장을 맨 앞에 놓았어요. 글을 처음 읽는 사람은 어떤 물건의 바늘인지 모를 수 있었어요. 민지는 시계라는 이름을 먼저 알려 주자고 했어요.''',
'''새로 본 시계에는 움직이는 바늘 없이 숫자만 나타났어요. 민지는 모든 시계에 두 바늘이 있다고 말하지 않았어요. 오늘 소개한 것이 바늘 시계라는 점을 밝혔어요. 한 물건의 모습을 설명할 때에도 그 설명이 어느 종류에 해당하는지 살피면 더 정확해져요.''',
[Q('긴바늘이 알려 주는 것은 무엇인가요?','몇 분인지 알려 주어요.',1,'긴바늘은 몇 분인지'),Q('시계 전체를 먼저 소개한 까닭은 무엇인가요?','어느 물건의 부분인지 알아야 뒤 설명을 따라가기 쉬워서예요.',2,'어느 물건의 부분인지 먼저'),Q('짧은바늘에 ‘몇 분’이라는 이름표를 붙였다면 어떻게 고쳐야 하나요?','짧은바늘은 몇 시인지 알려 준다고 고쳐요.',1,'짧은바늘은 몇 시인지'),Q('‘몇 분인지 알려 준다’만 쓰면 설명이 충분한가요?','어느 바늘인지 빠져 있어 긴바늘이라는 말을 넣어야 해요.',[1,2],'두 바늘의 하는 일')],
('자전거의 바퀴와 손잡이를 소개하려고 해요.','읽기 쉬운 차례는 무엇인가요?',['자전거 소개 → 바퀴 → 손잡이','손잡이만 설명하고 물건 이름은 빼기','바퀴는 손잡이라고 이름 바꾸기'],[2],'전체를 알린 뒤 각 부분을 설명해요.',['전체와 부분의 차례를 적용했어요.','어느 물건인지 알기 어려워요.','부분의 이름과 역할이 섞여요.']),[('부분','전체를 이루는 작은 것')],'바늘시계로 대상 범위를 한정하고 전체-부분 조직 원리를 새 물건에 적용.')

add('G1-EXP-W4','윷가락 설명을 고쳐요',
'''민지는 나무로 만든 윷가락 네 개를 보았어요. 한쪽 면은 평평하고 다른 쪽 면은 둥글었어요. 윷놀이에 쓰는 물건이라는 것도 알았어요. 민지는 모양과 쓰임을 함께 적으려고 했어요.
처음 쓴 글은 ‘윷가락은 네 개 나무 둥글다’였어요. 친구는 어느 면이 둥근지 알기 어렵다고 했어요. 민지는 ‘나무 윷가락은 네 개예요. 한쪽은 평평하고 다른 쪽은 둥글어요.’라고 고쳤어요. 말 사이의 관계가 분명해졌어요.''',
'''민지는 두 문장 끝에 마침표를 찍었어요. 문장을 나누니 어디에서 말이 끝나는지 알기 쉬웠어요. 마침표뿐 아니라 내용이 실제로 본 윷가락과 맞는지도 살폈어요. 글 모양과 뜻을 모두 확인한 거예요.''',
'''친구는 ‘모든 윷가락은 반드시 나무로만 만든다.’라고 썼어요. 민지가 본 것은 나무 윷가락이지만 다른 재료의 것은 확인하지 않았어요. 그래서 ‘우리가 본 윷가락은 나무로 만들었다.’라고 고쳤어요. 글을 바르게 고치는 일에는 말의 범위를 살피는 일도 들어가요.''',
[Q('민지가 본 윷가락의 두 면은 어떻게 다른가요?','한쪽은 평평하고 다른 쪽은 둥글어요.',1,'한쪽 면은 평평하고'),Q('고친 글이 더 알기 쉬운 까닭은 무엇인가요?','수와 재료, 어느 면이 둥근지의 관계를 문장으로 밝혔기 때문이에요.',2,'한쪽은 평평하고 다른 쪽은 둥글어요.'),Q('‘윷가락은 모두 둥근 면뿐이다’라는 문장은 어떻게 고쳐야 하나요?','평평한 면도 있다고 고쳐야 해요.',1,'한쪽 면은 평평하고'),Q('낱말만 여러 개 적으면 충분한 설명이 되나요?','낱말이 어떤 관계인지 알 수 있도록 이어야 해요.',2,'말 사이의 관계가 분명해졌어요.')],
('친구가 ‘상자 빨강 네모 담는다’라고 적었어요.','뜻이 분명해진 문장은 무엇인가요?',['빨간 상자는 네모 모양이에요. 물건을 담아요.','빨강은 담는다 상자.','상자는 물건이에요.'],[2],'낱말의 관계와 실제 정보를 살려 문장으로 고쳐요.',['색·모양·쓰임을 모두 살렸어요.','낱말 관계가 여전히 불분명해요.','중요한 특징과 쓰임이 빠졌어요.']),[('쓰임','어떤 일을 할 때 사용하는지')],'조사·마침표 확인만 하던 활동에 내용 정확성·관계 조직을 추가.')

add('G1-EXP-W5','도서관 안내는 목적이 있어요',
'''우리 학교 도서관에서는 여러 친구가 함께 책을 읽어요. 안내에는 ‘작은 소리로 말해요.’라고 쓰여 있어요. 다른 친구가 읽는 데 방해되지 않게 하려는 약속이에요.
또 ‘다 읽은 책은 반납 수레에 놓아요.’라고 쓰여 있어요. 이 도서관에서는 책을 맡은 사람이 자리를 확인해 정리해요. 민지는 예전 교실 책장처럼 아무 칸에 꽂으려다가 안내를 다시 읽었어요. 장소마다 정한 방법을 살펴야 해요.''',
'''민지는 ‘조용히 해!’라는 말 대신 누구를 위해 작은 소리로 말하는지도 안내에 적었어요. 약속과 까닭을 함께 읽으면 왜 지켜야 하는지 알기 쉬워요. 글씨를 크게 쓴 것만으로 좋은 안내가 되는 것은 아니에요.''',
'''다른 도서관의 안내에는 책을 정해진 책꽂이에 놓으라고 쓰여 있었어요. 민지는 어느 안내가 무조건 틀렸다고 하지 않았어요. 각각의 장소에서 정한 방법이 다를 수 있기 때문이에요. 같은 행동을 하기 전에도 지금 있는 곳의 안내를 확인하면 잘못 정리하는 일을 줄일 수 있어요.''',
[Q('이 도서관에서 다 읽은 책은 어디에 놓나요?','반납 수레에 놓아요.',2,'다 읽은 책은 반납 수레에 놓아요.'),Q('작은 소리로 말하는 까닭은 무엇인가요?','다른 친구가 읽는 데 방해되지 않게 하려는 거예요.',1,'방해되지 않게'),Q('예전 교실에서 하던 대로 아무 칸에 꽂으려 할 때 무엇을 해야 하나요?','지금 도서관의 안내를 다시 읽어요.',2,'안내를 다시 읽었어요.'),Q('‘책을 잘 정리하려면 어느 곳에서나 같은 자리에 놓으면 돼.’가 맞나요?','장소마다 정한 방법이 다를 수 있으므로 맞지 않아요.',2,'장소마다 정한 방법')],
('체육실에서는 쓴 공을 바구니에, 운동장에서는 보관함에 넣으라는 안내가 있어요. 지금은 체육실이에요.','어디에 공을 놓아야 하나요?',['체육실의 바구니','운동장의 보관함을 찾아 아무 때나 이동','안내와 관계없이 바닥'],[2],'지금 장소에 맞는 안내를 적용해요.',['현재 장소의 조건을 확인했어요.','다른 장소의 방법을 가져왔어요.','안내를 무시했어요.']),[('반납','빌리거나 사용한 것을 돌려줌')],'모든 도서관에서 직접 꽂는다는 지침을 없애고 장소 조건과 안내 목적을 판단.')

save(1)
